import pytest
from unittest.mock import patch

# code under test
import requests

def fetch_user(user_id):
    resp = requests.get(f'https://api.example.com/users/{user_id}')
    return resp.json()['name']

# fixture providing dummy JSON
@pytest.fixture
def dummy_response():
    class Dummy:
        def json(self):
            return {'name': 'Alice'}
    return Dummy()

def test_fetch_user(dummy_response):
    with patch('requests.get', return_value=dummy_response) as mock_get:
        name = fetch_user(42)
        assert name == 'Alice'
        mock_get.assert_called_once_with('https://api.example.com/users/42')

